"""Exception hierarchy for minilang."""


class MiniLangError(Exception):
    """Base class for all minilang errors.

    ``position`` is a 0-based offset into the source, or ``None`` when unknown.
    ``str(error)`` is the plain message with no position prefix.
    """

    def __init__(self, message: str, position: "int | None" = None):
        super().__init__(message)
        self.message = message
        self.position = position

    def __str__(self) -> str:
        return self.message


class LexError(MiniLangError):
    """Raised by the lexer for malformed input."""


class ParseError(MiniLangError):
    """Raised by the parser for syntactically invalid input."""


class EvalError(MiniLangError):
    """Raised by the evaluator for runtime errors."""

"""Lexer for minilang."""

from dataclasses import dataclass

from .errors import LexError

KEYWORDS = frozenset({"true", "false", "and", "or", "not"})

# Longest operators first so that "==" wins over "=".
_OPERATORS = ("==", "!=", "<=", ">=", "+", "-", "*", "/", "%", "^", "<", ">", "(", ")", ",")

_ESCAPES = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\"}


@dataclass(frozen=True)
class Token:
    kind: str  # one of NUMBER, STRING, IDENT, KEYWORD, OP
    value: object
    position: int


def _is_ident_start(ch: str) -> bool:
    return ch.isascii() and (ch.isalpha() or ch == "_")


def _is_ident_char(ch: str) -> bool:
    return ch.isascii() and (ch.isalnum() or ch == "_")


def _lex_number(source: str, start: int) -> "tuple[Token, int]":
    i = start
    n = len(source)
    int_digits = 0
    while i < n and source[i].isdigit():
        i += 1
        int_digits += 1
    frac_digits = 0
    if i < n and source[i] == ".":
        i += 1
        while i < n and source[i].isdigit():
            i += 1
            frac_digits += 1
        if frac_digits == 0:
            # ".5" is fine, "1." is not.
            raise LexError("number may not end with '.'", start)
    if int_digits == 0 and frac_digits == 0:
        raise LexError("unexpected character '.'", start)
    if i < n and source[i] in "eE":
        j = i + 1
        if j < n and source[j] in "+-":
            j += 1
        exp_digits = 0
        while j < n and source[j].isdigit():
            j += 1
            exp_digits += 1
        if exp_digits == 0:
            raise LexError("malformed exponent in number", start)
        i = j
    return Token("NUMBER", float(source[start:i]), start), i


def _lex_string(source: str, start: int) -> "tuple[Token, int]":
    i = start + 1
    n = len(source)
    chars = []
    while True:
        if i >= n:
            raise LexError("unterminated string", start)
        ch = source[i]
        if ch == '"':
            return Token("STRING", "".join(chars), start), i + 1
        if ch == "\n":
            raise LexError("newline in string", i)
        if ch == "\\":
            if i + 1 >= n:
                raise LexError("unterminated string", start)
            esc = source[i + 1]
            if esc not in _ESCAPES:
                raise LexError(f"invalid escape sequence '\\{esc}'", i)
            chars.append(_ESCAPES[esc])
            i += 2
            continue
        chars.append(ch)
        i += 1


def tokenize(source: str) -> "list[Token]":
    tokens: list[Token] = []
    i = 0
    n = len(source)
    while i < n:
        ch = source[i]
        if ch in " \t\r\n":
            i += 1
        elif ch == "#":
            while i < n and source[i] != "\n":
                i += 1
        elif ch.isdigit() or (ch == "." and i + 1 < n and source[i + 1].isdigit()):
            tok, i = _lex_number(source, i)
            tokens.append(tok)
        elif ch == '"':
            tok, i = _lex_string(source, i)
            tokens.append(tok)
        elif _is_ident_start(ch):
            j = i + 1
            while j < n and _is_ident_char(source[j]):
                j += 1
            word = source[i:j]
            kind = "KEYWORD" if word in KEYWORDS else "IDENT"
            tokens.append(Token(kind, word, i))
            i = j
        else:
            for op in _OPERATORS:
                if source.startswith(op, i):
                    tokens.append(Token("OP", op, i))
                    i += len(op)
                    break
            else:
                if ch == "=":
                    raise LexError("unexpected '=' (did you mean '==')?", i)
                raise LexError(f"unexpected character {ch!r}", i)
    return tokens

"""Recursive-descent parser for minilang."""

from dataclasses import dataclass

from .errors import ParseError
from .lexer import Token, tokenize


@dataclass(frozen=True)
class Node:
    position: int


@dataclass(frozen=True)
class Number(Node):
    value: float


@dataclass(frozen=True)
class String(Node):
    value: str


@dataclass(frozen=True)
class Boolean(Node):
    value: bool


@dataclass(frozen=True)
class Variable(Node):
    name: str


@dataclass(frozen=True)
class Call(Node):
    name: str
    args: "tuple[Node, ...]"


@dataclass(frozen=True)
class Unary(Node):
    op: str  # "-" or "not"
    operand: Node


@dataclass(frozen=True)
class Binary(Node):
    op: str
    left: Node
    right: Node


_COMPARISON_OPS = ("==", "!=", "<", "<=", ">", ">=")


class _Parser:
    def __init__(self, tokens: "list[Token]", source_length: int):
        self.tokens = tokens
        self.pos = 0
        self.end = source_length

    # -- helpers -----------------------------------------------------------

    def _peek(self) -> "Token | None":
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def _position(self) -> int:
        tok = self._peek()
        return tok.position if tok is not None else self.end

    def _advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _at_op(self, *ops: str) -> bool:
        tok = self._peek()
        return tok is not None and tok.kind == "OP" and tok.value in ops

    def _at_keyword(self, word: str) -> bool:
        tok = self._peek()
        return tok is not None and tok.kind == "KEYWORD" and tok.value == word

    def _expect_op(self, op: str) -> Token:
        if not self._at_op(op):
            tok = self._peek()
            found = "end of input" if tok is None else repr(tok.value)
            raise ParseError(f"expected '{op}', got {found}", self._position())
        return self._advance()

    # -- grammar -----------------------------------------------------------

    def parse(self) -> Node:
        if not self.tokens:
            raise ParseError("empty expression", self.end)
        node = self.expr()
        if self._peek() is not None:
            tok = self._peek()
            raise ParseError(f"unexpected token {tok.value!r}", tok.position)
        return node

    def expr(self) -> Node:
        return self.or_expr()

    def or_expr(self) -> Node:
        node = self.and_expr()
        while self._at_keyword("or"):
            tok = self._advance()
            right = self.and_expr()
            node = Binary(tok.position, "or", node, right)
        return node

    def and_expr(self) -> Node:
        node = self.not_expr()
        while self._at_keyword("and"):
            tok = self._advance()
            right = self.not_expr()
            node = Binary(tok.position, "and", node, right)
        return node

    def not_expr(self) -> Node:
        if self._at_keyword("not"):
            tok = self._advance()
            return Unary(tok.position, "not", self.not_expr())
        return self.comparison()

    def comparison(self) -> Node:
        node = self.additive()
        if self._at_op(*_COMPARISON_OPS):
            tok = self._advance()
            right = self.additive()
            node = Binary(tok.position, tok.value, node, right)
            if self._at_op(*_COMPARISON_OPS):
                raise ParseError(
                    "comparison operators cannot be chained", self._position()
                )
        return node

    def additive(self) -> Node:
        node = self.multiplicative()
        while self._at_op("+", "-"):
            tok = self._advance()
            right = self.multiplicative()
            node = Binary(tok.position, tok.value, node, right)
        return node

    def multiplicative(self) -> Node:
        node = self.unary()
        while self._at_op("*", "/", "%"):
            tok = self._advance()
            right = self.unary()
            node = Binary(tok.position, tok.value, node, right)
        return node

    def unary(self) -> Node:
        if self._at_op("-"):
            tok = self._advance()
            return Unary(tok.position, "-", self.unary())
        return self.power()

    def power(self) -> Node:
        node = self.primary()
        if self._at_op("^"):
            tok = self._advance()
            right = self.unary()
            node = Binary(tok.position, "^", node, right)
        return node

    def primary(self) -> Node:
        tok = self._peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.end)
        if tok.kind == "NUMBER":
            self._advance()
            return Number(tok.position, tok.value)
        if tok.kind == "STRING":
            self._advance()
            return String(tok.position, tok.value)
        if tok.kind == "KEYWORD" and tok.value in ("true", "false"):
            self._advance()
            return Boolean(tok.position, tok.value == "true")
        if tok.kind == "IDENT":
            self._advance()
            if self._at_op("("):
                self._advance()
                args = []
                if not self._at_op(")"):
                    args.append(self.expr())
                    while self._at_op(","):
                        self._advance()
                        args.append(self.expr())
                self._expect_op(")")
                return Call(tok.position, tok.value, tuple(args))
            return Variable(tok.position, tok.value)
        if tok.kind == "OP" and tok.value == "(":
            self._advance()
            node = self.expr()
            self._expect_op(")")
            return node
        raise ParseError(f"unexpected token {tok.value!r}", tok.position)


def parse(source: str) -> Node:
    tokens = tokenize(source)
    return _Parser(tokens, len(source)).parse()

"""Built-in functions and value formatting for minilang."""

import math

from .errors import EvalError


# -- formatting -------------------------------------------------------------

def type_name(value: object) -> str:
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "string"
    return type(value).__name__


def format_number(value: float) -> str:
    if math.isfinite(value) and value.is_integer():
        return str(int(value))
    return repr(value)


_REESCAPE = {"\\": "\\\\", '"': '\\"', "\n": "\\n", "\t": "\\t", "\r": "\\r"}


def format_value(value: object, quote_strings: bool = True) -> str:
    """Render a value the way the REPL does.

    ``str()`` in minilang uses ``quote_strings=False`` so strings pass through unchanged.
    """
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, float):
        return format_number(value)
    if isinstance(value, str):
        if not quote_strings:
            return value
        return '"' + "".join(_REESCAPE.get(ch, ch) for ch in value) + '"'
    raise EvalError(f"unsupported value: {value!r}")


# -- argument checking ---------------------------------------------------------

def _check_arity(name: str, args: list, expected: int) -> None:
    if len(args) != expected:
        raise EvalError(f"{name}() takes {expected} argument(s), got {len(args)}")


def _check_number(name: str, value: object) -> float:
    if type(value) is not float:
        raise EvalError(f"{name}() expects a number, got {type_name(value)}")
    return value


def _check_string(name: str, value: object) -> str:
    if type(value) is not str:
        raise EvalError(f"{name}() expects a string, got {type_name(value)}")
    return value


# -- strict builtins (arguments already evaluated) ----------------------------

def _abs(args: list) -> float:
    _check_arity("abs", args, 1)
    return abs(_check_number("abs", args[0]))


def _min(args: list) -> float:
    if not args:
        raise EvalError("min() takes at least 1 argument(s), got 0")
    return min(_check_number("min", a) for a in args)


def _max(args: list) -> float:
    if not args:
        raise EvalError("max() takes at least 1 argument(s), got 0")
    return max(_check_number("max", a) for a in args)


def _round(args: list) -> float:
    if len(args) not in (1, 2):
        raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}")
    x = _check_number("round", args[0])
    if len(args) == 1:
        if not math.isfinite(x):
            raise EvalError("round() cannot round a non-finite number")
        return float(round(x))
    n = _check_number("round", args[1])
    if not n.is_integer():
        raise EvalError(f"round() expects a whole number of digits, got {format_number(n)}")
    return float(round(x, int(n)))


def _len(args: list) -> float:
    _check_arity("len", args, 1)
    return float(len(_check_string("len", args[0])))


def _upper(args: list) -> str:
    _check_arity("upper", args, 1)
    return _check_string("upper", args[0]).upper()


def _lower(args: list) -> str:
    _check_arity("lower", args, 1)
    return _check_string("lower", args[0]).lower()


def _str(args: list) -> str:
    _check_arity("str", args, 1)
    return format_value(args[0], quote_strings=False)


def _num(args: list) -> float:
    _check_arity("num", args, 1)
    s = _check_string("num", args[0])
    # Reject forms Python's float() accepts but minilang does not (underscores,
    # inf/nan); everything else is delegated to float().
    stripped = s.strip()
    if "_" in stripped or not any(c.isdigit() for c in stripped):
        raise EvalError(f"num() cannot parse {s!r}")
    try:
        return float(stripped)
    except ValueError:
        raise EvalError(f"num() cannot parse {s!r}") from None


BUILTINS = {
    "abs": _abs,
    "min": _min,
    "max": _max,
    "round": _round,
    "len": _len,
    "upper": _upper,
    "lower": _lower,
    "str": _str,
    "num": _num,
}


# -- lazy builtins (receive unevaluated argument nodes) ----------------------

def _if(arg_nodes: tuple, evaluate_node) -> object:
    if len(arg_nodes) != 3:
        raise EvalError(f"if() takes 3 argument(s), got {len(arg_nodes)}")
    cond = evaluate_node(arg_nodes[0])
    if type(cond) is not bool:
        raise EvalError(f"if() expects a boolean condition, got {type_name(cond)}")
    return evaluate_node(arg_nodes[1] if cond else arg_nodes[2])


LAZY_BUILTINS = {
    "if": _if,
}

"""Tree-walking evaluator for minilang."""

import math

from .builtins import BUILTINS, LAZY_BUILTINS, type_name
from .errors import EvalError
from .parser import (
    Binary,
    Boolean,
    Call,
    Node,
    Number,
    String,
    Unary,
    Variable,
    parse,
)


def _is_number(value: object) -> bool:
    return type(value) is float


def _is_bool(value: object) -> bool:
    return type(value) is bool


def _require_numbers(op: str, left: object, right: object, position: int) -> None:
    if not (_is_number(left) and _is_number(right)):
        raise EvalError(
            f"unsupported operand types for '{op}': {type_name(left)} and {type_name(right)}",
            position,
        )


class _Evaluator:
    def __init__(self, env: dict):
        self.env = env

    def eval(self, node: Node) -> object:
        method = getattr(self, f"_eval_{type(node).__name__}")
        return method(node)

    def _eval_Number(self, node: Number) -> float:
        return node.value

    def _eval_String(self, node: String) -> str:
        return node.value

    def _eval_Boolean(self, node: Boolean) -> bool:
        return node.value

    def _eval_Variable(self, node: Variable) -> object:
        if node.name not in self.env:
            raise EvalError(f"undefined variable: {node.name}", node.position)
        value = self.env[node.name]
        # bool is checked by exact type so int/bool confusion cannot slip through.
        if type(value) not in (float, str, bool):
            raise EvalError(
                f"unsupported value for {node.name}: {value!r}", node.position
            )
        return value

    def _eval_Call(self, node: Call) -> object:
        if node.name in LAZY_BUILTINS:
            return LAZY_BUILTINS[node.name](node.args, self.eval)
        if node.name in BUILTINS:
            args = [self.eval(arg) for arg in node.args]
            return BUILTINS[node.name](args)
        raise EvalError(f"undefined function: {node.name}", node.position)

    def _eval_Unary(self, node: Unary) -> object:
        value = self.eval(node.operand)
        if node.op == "-":
            if not _is_number(value):
                raise EvalError(
                    f"unary '-' requires a number, got {type_name(value)}", node.position
                )
            return -value
        if node.op == "not":
            if not _is_bool(value):
                raise EvalError(
                    f"'not' requires a boolean, got {type_name(value)}", node.position
                )
            return not value
        raise EvalError(f"unknown unary operator {node.op!r}", node.position)

    def _eval_Binary(self, node: Binary) -> object:
        op = node.op
        if op in ("and", "or"):
            left = self.eval(node.left)
            if not _is_bool(left):
                raise EvalError(
                    f"'{op}' requires booleans, got {type_name(left)}", node.position
                )
            if op == "and" and not left:
                return False
            if op == "or" and left:
                return True
            right = self.eval(node.right)
            if not _is_bool(right):
                raise EvalError(
                    f"'{op}' requires booleans, got {type_name(right)}", node.position
                )
            return right

        left = self.eval(node.left)
        right = self.eval(node.right)
        pos = node.position

        if op == "==":
            return type(left) is type(right) and left == right
        if op == "!=":
            return not (type(left) is type(right) and left == right)
        if op in ("<", "<=", ">", ">="):
            same_numbers = _is_number(left) and _is_number(right)
            same_strings = type(left) is str and type(right) is str
            if not (same_numbers or same_strings):
                raise EvalError(
                    f"cannot compare {type_name(left)} and {type_name(right)} with '{op}'",
                    pos,
                )
            if op == "<":
                return left < right
            if op == "<=":
                return left <= right
            if op == ">":
                return left > right
            return left >= right
        if op == "+":
            if _is_number(left) and _is_number(right):
                return left + right
            if type(left) is str and type(right) is str:
                return left + right
            raise EvalError(
                f"unsupported operand types for '+': {type_name(left)} and {type_name(right)}",
                pos,
            )
        if op == "-":
            _require_numbers(op, left, right, pos)
            return left - right
        if op == "*":
            _require_numbers(op, left, right, pos)
            return left * right
        if op == "/":
            _require_numbers(op, left, right, pos)
            if right == 0:
                raise EvalError("division by zero", pos)
            return left / right
        if op == "%":
            _require_numbers(op, left, right, pos)
            if right == 0:
                raise EvalError("modulo by zero", pos)
            return left % right
        if op == "^":
            _require_numbers(op, left, right, pos)
            try:
                result = left ** right
            except ZeroDivisionError:
                raise EvalError("zero cannot be raised to a negative power", pos) from None
            except OverflowError:
                raise EvalError("result of '^' is too large", pos) from None
            if not isinstance(result, float) or math.isnan(result):
                raise EvalError("result of '^' is not a real number", pos)
            return result
        raise EvalError(f"unknown operator {op!r}", pos)


def evaluate(source: str, env: "dict | None" = None) -> object:
    """Parse and evaluate ``source``. ``env`` is read but never mutated."""
    tree = parse(source)
    return evaluate_node(tree, env)


def evaluate_node(tree: Node, env: "dict | None" = None) -> object:
    return _Evaluator(env if env is not None else {}).eval(tree)

"""REPL for minilang, runnable as ``python -m minilang``."""

import re
import sys

from .builtins import format_value
from .errors import MiniLangError
from .evaluator import evaluate
from .lexer import KEYWORDS

# `<ident> = <expr>` where the `=` is not part of `==`.
_ASSIGNMENT = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)(.*)$", re.DOTALL)


def _handle_line(line: str, env: dict, out) -> bool:
    """Process one input line. Returns False when the REPL should stop."""
    stripped = line.strip()
    if not stripped:
        return True
    if stripped == ":quit":
        return False
    if stripped == ":vars":
        for name in sorted(env):
            out.write(f"{name} = {format_value(env[name])}\n")
        return True

    match = _ASSIGNMENT.match(line)
    # Keywords are not identifiers, so `true = 1` falls through to expression
    # evaluation (and reports the stray `=` as an error).
    if match and match.group(1) not in KEYWORDS:
        name, expr = match.group(1), match.group(2)
        try:
            env[name] = evaluate(expr, env)
        except MiniLangError as exc:
            out.write(f"error: {exc}\n")
        return True

    try:
        out.write(format_value(evaluate(line, env)) + "\n")
    except MiniLangError as exc:
        out.write(f"error: {exc}\n")
    return True


def main(stdin=None, stdout=None) -> int:
    stdin = stdin if stdin is not None else sys.stdin
    stdout = stdout if stdout is not None else sys.stdout
    env: dict = {}
    for line in stdin:
        if not _handle_line(line, env, stdout):
            break
        stdout.flush()
    stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
